from pathlib import Path
import json
root=Path.cwd()
spec=json.loads((root/"control/project_tasks/DEV-PRED-A2Z-POSTBUILD-RETRY-20261006-E106.json").read_text())
need={
 "control/jobs/full_a2z_governed_v4.py",
 "control/codex_supervisor/experiment_gate.py",
 "control/codex_supervisor/model_quality_gate.py",
}
found={}
for op in spec["operations"]:
    if op.get("type")=="write_text" and op.get("path") in need:
        found[op["path"]]=op["content"]
missing=need-set(found)
if missing:
    raise SystemExit("MISSING_E106_SOURCES:"+",".join(sorted(missing)))
for rel,content in found.items():
    p=root/rel
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(content,encoding="utf-8")
print("E116_HYDRATED=1")
